private int counter = 0;

private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

}

private void xrTableCell6_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (GetCurrentColumnValue("KODI") != null)
            {
                counter++;
                xrTableCell6.Text = counter.ToString();
            }
            else xrTableCell6.Text = "";
}



private void pictureBox1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if ((GetCurrentColumnValue("arkiva_path") != System.DBNull.Value || GetCurrentColumnValue("arkiva_path") != null)&& Convert.ToString(GetCurrentColumnValue("arkiva_path")) != "" && (AlphaWebReports.raporteUtil.KontrolloEkzistencImazhi(Convert.ToString(GetCurrentColumnValue("arkiva_path")))))
	{
		AlphaWebReports.raporteUtil.BashkangjitImazh(pictureBox1, Convert.ToString(GetCurrentColumnValue("arkiva_path")));
	}else
		pictureBox1.Image = null;
}
